    /**
     * Selects a collection of HistUsuario objects pre-filled with their Dependencia objects.
     * @param      Criteria  $criteria
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return array           Array of HistUsuario objects.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinDependencia(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(HistUsuarioPeer::DATABASE_NAME);
        }

        HistUsuarioPeer::addSelectColumns($criteria);
        $startcol = HistUsuarioPeer::NUM_HYDRATE_COLUMNS;
        DependenciaPeer::addSelectColumns($criteria);

        $criteria->addJoin(HistUsuarioPeer::DEPENDENCIA_ID, DependenciaPeer::DEPENDENCIA_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseHistUsuarioPeer', $criteria, $con);
        }

        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = HistUsuarioPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = HistUsuarioPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {

                $cls = HistUsuarioPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                HistUsuarioPeer::addInstanceToPool($obj1, $key1);
            } // if $obj1 already loaded

            $key2 = DependenciaPeer::getPrimaryKeyHashFromRow($row, $startcol);
            if ($key2 !== null) {
                $obj2 = DependenciaPeer::getInstanceFromPool($key2);
                if (!$obj2) {

                    $cls = DependenciaPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol);
                    DependenciaPeer::addInstanceToPool($obj2, $key2);
                } // if obj2 already loaded

                // Add the $obj1 (HistUsuario) to $obj2 (Dependencia)
                $obj2->addHistUsuario($obj1);

            } // if joined row was not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


