                    DependenciaPeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (HistUsuario) to the collection in $obj2 (Dependencia)
                $obj2->addHistUsuario($obj1);

            } // if joined row is not null

                // Add objects for joined Regional rows

                $key3 = RegionalPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = RegionalPeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = RegionalPeer::getOMClass();

