                } // if $obj4 already loaded

                // Add the $obj1 (HistUsuario) to the collection in $obj4 (Cargo)
                $obj4->addHistUsuario($obj1);

            } // if joined row is not null

                // Add objects for joined EstadoUsuario rows

                $key5 = EstadoUsuarioPeer::getPrimaryKeyHashFromRow($row, $startcol5);
                if ($key5 !== null) {
                    $obj5 = EstadoUsuarioPeer::getInstanceFromPool($key5);
