                    $obj5->hydrate($row, $startcol5);
                    EstadoUsuarioPeer::addInstanceToPool($obj5, $key5);
                } // if $obj5 already loaded

                // Add the $obj1 (HistUsuario) to the collection in $obj5 (EstadoUsuario)
                $obj5->addHistUsuario($obj1);

            } // if joined row is not null

                // Add objects for joined TipoProcesoCom rows

                $key6 = TipoProcesoComPeer::getPrimaryKeyHashFromRow($row, $startcol6);
                if ($key6 !== null) {
                    $obj6 = TipoProcesoComPeer::getInstanceFromPool($key6);
