                // Add the $obj1 (HistUsuario) to the collection in $obj6 (TipoProcesoCom)
                $obj6->addHistUsuario($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
